import json
from typing import Any

from mlflow.tracing.constant import GenAiSemconvKey
from mlflow.tracing.export.genai_semconv.converter import GenAiSemconvConverter


class BedrockConverseConverter(GenAiSemconvConverter):
    def convert_inputs(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        messages = inputs.get("messages")
        if not isinstance(messages, list):
            return None
        return [_convert_message(m) for m in messages]

    def convert_system_instructions(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        system = inputs.get("system")
        if not isinstance(system, list):
            return None
        result = [
            {"type": "text", "content": block["text"]}
            for block in system
            if isinstance(block, dict) and "text" in block
        ]
        return result or None

    def convert_outputs(self, outputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        output = outputs.get("output")
        if not isinstance(output, dict):
            return None
        message = output.get("message")
        if not isinstance(message, dict):
            return None
        return [_convert_message(message)]

    def extract_request_params(self, inputs: dict[str, Any]) -> dict[str, Any]:
        params: dict[str, Any] = {}
        inference_config = inputs.get("inferenceConfig") or {}
        if (temperature := inference_config.get("temperature")) is not None:
            params[GenAiSemconvKey.REQUEST_TEMPERATURE] = temperature
        if (max_tokens := inference_config.get("maxTokens")) is not None:
            params[GenAiSemconvKey.REQUEST_MAX_TOKENS] = max_tokens
        if (top_p := inference_config.get("topP")) is not None:
            params[GenAiSemconvKey.REQUEST_TOP_P] = top_p

        if tool_config := inputs.get("toolConfig"):
            tools = tool_config.get("tools", [])
            params[GenAiSemconvKey.TOOL_DEFINITIONS] = json.dumps(
                [_convert_tool_definition(t) for t in tools]
            )
        return params

    def extract_response_attrs(self, outputs: dict[str, Any]) -> dict[str, Any]:
        return {}


def _convert_message(msg: dict[str, Any]) -> dict[str, Any]:
    role = msg.get("role", "user")
    content = msg.get("content")

    if isinstance(content, str):
        return {"role": role, "parts": [{"type": "text", "content": content}]}

    if isinstance(content, list):
        parts = [_convert_block(b) for b in content]
        # Bedrock delivers tool results inside a "user" role message. Override it to "tool".
        if parts and all(p.get("type") == "tool_call_response" for p in parts):
            return {"role": "tool", "parts": parts}
        return {"role": role, "parts": parts}

    return {"role": role, "parts": []}


def _convert_block(block: dict[str, Any]) -> dict[str, Any]:
    if "text" in block:
        return {"type": "text", "content": block.get("text", "")}
    if "image" in block:
        return _convert_image(block["image"])
    if "toolUse" in block:
        tool_use = block["toolUse"]
        return {
            "type": "tool_call",
            "id": tool_use.get("toolUseId", ""),
            "name": tool_use.get("name", ""),
            "arguments": tool_use.get("input"),
        }
    if "toolResult" in block:
        return _convert_tool_result(block["toolResult"])
    # Fallback to text with the dumped content block
    return {"type": "text", "content": json.dumps(block)}


def _convert_image(image: dict) -> dict:
    fmt = image.get("format", "")
    source = image.get("source", {})
    data = source.get("bytes")
    content = base64.b64encode(data).decode("utf-8") if isinstance(data, bytes) else data
    return {
        "type": "blob",
        "modality": "image",
        "mime_type": f"image/{fmt}",
        "content": content,
    }


def _convert_tool_result(tool_result: dict[str, Any]) -> dict[str, Any]:
    results = []
    for block in tool_result.get("content", []):
        if "json" in block:
            results.append(block["json"])
        elif "text" in block:
            results.append(block["text"])
        else:
            results.append(block)
    value = results[0] if len(results) == 1 else results
    result = value if isinstance(value, str) else json.dumps(value)
    return {
        "type": "tool_call_response",
        "id": tool_result.get("toolUseId", ""),
        "result": result,
    }


def _convert_tool_definition(tool: dict[str, Any]) -> dict[str, Any]:
    spec = tool.get("toolSpec", {})
    result: dict[str, Any] = {"name": spec.get("name", "")}
    if (description := spec.get("description")) is not None:
        result["description"] = description
    if (params := spec.get("inputSchema", {}).get("json")) is not None:
        result["parameters"] = params
    return result
